function GlassCard({ title, description, icon }) {
  return (
    <div className="group relative p-8 rounded-2xl bg-white/5 backdrop-blur-xl border border-white/10 hover:border-white/20 transition-all duration-300 hover:-translate-y-1">
      {/* Gradient overlay on hover */}
      <div className="absolute inset-0 rounded-2xl bg-gradient-to-br from-purple-500/10 to-pink-500/10 opacity-0 group-hover:opacity-100 transition-opacity" />
      <div className="relative z-10">
        <div className="w-14 h-14 mb-6 rounded-xl bg-gradient-to-br from-purple-500 to-pink-500 flex items-center justify-center text-white text-2xl">
          {icon || '✨'}
        </div>
        <h3 className="text-xl font-bold text-white mb-3">{title || 'Feature Title'}</h3>
        <p className="text-gray-400 leading-relaxed">{description || 'Describe your amazing feature here with compelling copy that converts visitors.'}</p>
      </div>
    </div>
  );
}

function BentoCard({ title, description, className, children }) {
  return (
    <div className={`group relative overflow-hidden rounded-3xl bg-neutral-900 p-8 ${className || ''}`}>
      {/* Gradient background */}
      <div className="absolute inset-0 bg-gradient-to-br from-neutral-800/50 to-neutral-900/50" />
      {/* Hover glow */}
      <div className="absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity duration-500 bg-[radial-gradient(600px_circle_at_var(--mouse-x)_var(--mouse-y),rgba(255,255,255,0.06),transparent_40%)]" />
      <div className="relative z-10">
        <h3 className="text-2xl font-bold text-white mb-2">{title || 'Card Title'}</h3>
        <p className="text-neutral-400 mb-6">{description || 'Card description goes here'}</p>
        {children}
      </div>
    </div>
  );
}

function ProductCard({ image, name, price, originalPrice, rating }) {
  return (
    <div className="group bg-white rounded-2xl overflow-hidden shadow-sm hover:shadow-xl transition-all duration-300">
      {/* Image */}
      <div className="relative aspect-square overflow-hidden bg-gray-100">
        <img 
          src={image || 'https://images.unsplash.com/photo-1523275335684-37898b6baf30?w=400&h=400&fit=crop'} 
          alt={name || 'Product'}
          className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
        />
        {originalPrice && (
          <div className="absolute top-4 left-4 px-3 py-1 bg-red-500 text-white text-sm font-medium rounded-full">
            Sale
          </div>
        )}
        <button className="absolute top-4 right-4 w-10 h-10 bg-white rounded-full flex items-center justify-center shadow-md opacity-0 group-hover:opacity-100 transition-opacity hover:bg-gray-100">
          <svg className="w-5 h-5 text-gray-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z" />
          </svg>
        </button>
      </div>
      {/* Content */}
      <div className="p-5">
        <h3 className="font-semibold text-gray-900 mb-2">{name || 'Product Name'}</h3>
        <div className="flex items-center gap-2 mb-3">
          <div className="flex items-center text-yellow-400">
            {'★'.repeat(Math.floor(rating || 5))}
          </div>
          <span className="text-sm text-gray-500">({rating || '5.0'})</span>
        </div>
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <span className="text-xl font-bold text-gray-900">${price || '99'}</span>
            {originalPrice && (
              <span className="text-sm text-gray-400 line-through">${originalPrice}</span>
            )}
          </div>
          <button className="px-4 py-2 bg-black text-white text-sm font-medium rounded-lg hover:bg-gray-800 transition-colors">
            Add to Cart
          </button>
        </div>
      </div>
    </div>
  );
}

function TestimonialCard({ quote, author, role, company, avatar, rating }) {
  return (
    <div className="bg-white p-8 rounded-2xl shadow-lg border border-gray-100">
      {/* Rating */}
      <div className="flex items-center gap-1 mb-6 text-yellow-400">
        {'★'.repeat(rating || 5)}
      </div>
      {/* Quote */}
      <blockquote className="text-gray-700 text-lg leading-relaxed mb-6">
        "{quote || 'This product has completely transformed how we work. The team is incredibly responsive and the features are exactly what we needed.'}"
      </blockquote>
      {/* Author */}
      <div className="flex items-center gap-4">
        <img 
          src={avatar || 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=100&h=100&fit=crop'} 
          alt={author || 'Customer'}
          className="w-12 h-12 rounded-full object-cover"
        />
        <div>
          <div className="font-semibold text-gray-900">{author || 'John Smith'}</div>
          <div className="text-sm text-gray-500">{role || 'CEO'} at {company || 'Acme Inc'}</div>
        </div>
      </div>
    </div>
  );
}
